import React, { useEffect, useState } from 'react';
import { Card, Typography, Space, Input, InputNumber, Button, Table, Checkbox, message, Modal, Select } from 'antd';
import HyperloopDSLValidator from '../components/HyperloopDSLValidator';
import { getTelegramUser } from '../api';

const buildAuthHeaders = (): HeadersInit => {
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  const tgId = sessionStorage.getItem('tg_id') || getTelegramUser()?.id?.toString();
  if (tgId) headers['X-Telegram-User-ID'] = tgId;
  const token = sessionStorage.getItem('token');
  if (token) headers['Authorization'] = `Bearer ${token}`;
  return headers;
};

const AdminPanel: React.FC = () => {
  const [promoLoading, setPromoLoading] = useState(false);
  const [promoCodes, setPromoCodes] = useState<Array<any>>([]);
  const [redemptions, setRedemptions] = useState<Array<any>>([]);
  const [newPromoCode, setNewPromoCode] = useState('');
  const [newPromoRole, setNewPromoRole] = useState('basic');
  const [newPromoLimit, setNewPromoLimit] = useState<number | undefined>();
  const [requestsLoading, setRequestsLoading] = useState(false);
  const [regRequests, setRegRequests] = useState<Array<any>>([]);
  const [docPrivacyUrl, setDocPrivacyUrl] = useState('');
  const [docSecurityUrl, setDocSecurityUrl] = useState('');
  const [dutyAdminTgId, setDutyAdminTgId] = useState('');

  const [devBranch, setDevBranch] = useState('p48r-dev');
  const [devSession, setDevSession] = useState('dev-001');
  const [devConnectLoading, setDevConnectLoading] = useState(false);
  const [locksLoading, setLocksLoading] = useState(false);
  const [myBranches, setMyBranches] = useState<Array<any>>([]);

  // === P51 Personality Admin UI state ===
  const [activePersonality, setActivePersonality] = useState<any>(null);
  const [loadingPersonality, setLoadingPersonality] = useState<boolean>(false);
  const [defineModalOpen, setDefineModalOpen] = useState<boolean>(false);
  const [defineSex, setDefineSex] = useState<'male'|'female'>('male');
  const [defineVersion, setDefineVersion] = useState<string>('v1');
  const [defineAnima, setDefineAnima] = useState<number | undefined>(0.3);

  const [normKey, setNormKey] = useState('');
  const [normTitle, setNormTitle] = useState('');
  const [normSeverity, setNormSeverity] = useState<number>(0.8);
  const [normScope, setNormScope] = useState('duty');

  const [traitKey, setTraitKey] = useState('conscientiousness');
  const [traitFamily, setTraitFamily] = useState('OCEAN');
  const [traitTendency, setTraitTendency] = useState<number>(0.7);
  const [traitStability, setTraitStability] = useState<number>(0.8);

  const [attachKey, setAttachKey] = useState('family');
  const [attachWeight, setAttachWeight] = useState<number>(0.7);

  const [policyKey, setPolicyKey] = useState('processor.multipliers');
  const [policyValue, setPolicyValue] = useState<string>(JSON.stringify({ appraise: 1.05, decide: 1.03, rank: 1.07, offsets: { appraise: 0.01, decide: 0.0, rank: 0.02 } }, null, 2));

  const [twoKeysReqId, setTwoKeysReqId] = useState<string>('');
  const [tkOperation, setTkOperation] = useState<string>('personality.activate');
  const [tkScope, setTkScope] = useState<string>('p51');
  const [tkReason, setTkReason] = useState<string>('switch active personality');
  const [tkTtl, setTkTtl] = useState<number | undefined>(60);
  const [norms, setNorms] = useState<Array<any>>([]);
  const [traits, setTraits] = useState<Array<any>>([]);
  const [attachments, setAttachments] = useState<Array<any>>([]);
  const [policies, setPolicies] = useState<Array<any>>([]);
  const [links, setLinks] = useState<Array<any>>([]);
  const [listsLoading, setListsLoading] = useState<boolean>(false);
  const [batchLoading, setBatchLoading] = useState<boolean>(false);

  const reloadPersonalityLists = async () => {
    const pid = activePersonality?.id;
    if (!pid) return;
    try {
      setListsLoading(true);
      const [n, t, a, p, l] = await Promise.all([
        fetch(`/api/admin/personality/norms?personality_id=${encodeURIComponent(pid)}`, { headers: buildHeaders() }).then(async r=>{ if(!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); }).catch(()=>({items:[]})),
        fetch(`/api/admin/personality/traits?personality_id=${encodeURIComponent(pid)}`, { headers: buildHeaders() }).then(async r=>{ if(!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); }).catch(()=>({items:[]})),
        fetch(`/api/admin/personality/attachments?personality_id=${encodeURIComponent(pid)}`, { headers: buildHeaders() }).then(async r=>{ if(!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); }).catch(()=>({items:[]})),
        fetch(`/api/admin/personality/policies?personality_id=${encodeURIComponent(pid)}`, { headers: buildHeaders() }).then(async r=>{ if(!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); }).catch(()=>({items:[]})),
        fetch(`/api/admin/personality/links?personality_id=${encodeURIComponent(pid)}`, { headers: buildHeaders() }).then(async r=>{ if(!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); }).catch(()=>({items:[]})),
      ]);
      setNorms(n.items||[]); setTraits(t.items||[]); setAttachments(a.items||[]); setPolicies(p.items||[]); setLinks(l.items||[]);
    } catch { message.error('Ошибка загрузки списков личности'); }
    finally { setListsLoading(false); }
  };

  const loadPromo = async () => {
    try {
      setPromoLoading(true);
      const resp = await fetch('/api/admin/promo/codes', { headers: buildAuthHeaders() });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const data = await resp.json();
      setPromoCodes(Array.isArray(data.items) ? data.items : []);
    } catch { message.error('Ошибка загрузки промокодов'); } finally { setPromoLoading(false); }
  };

  const loadRedemptions = async () => {
    try {
      const resp = await fetch('/api/admin/promo/redemptions', { headers: buildAuthHeaders() });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const data = await resp.json();
      setRedemptions(Array.isArray(data.items) ? data.items : []);
    } catch { /* no-op */ }
  };

  const createPromo = async () => {
    const code = newPromoCode.trim();
    const role = newPromoRole.trim();
    if (!code || !role) { message.warning('Укажите код и роль'); return; }
    try {
      setPromoLoading(true);
      const resp = await fetch('/api/admin/promo/codes', {
        method: 'POST', headers: buildAuthHeaders(), body: JSON.stringify({ code, role_name: role, total_limit: newPromoLimit || null, is_active: true })
      });
      if (!resp.ok) throw new Error();
      setNewPromoCode(''); setNewPromoRole('basic'); setNewPromoLimit(undefined);
      await loadPromo();
      message.success('Промокод создан');
    } catch { message.error('Не удалось создать промокод'); } finally { setPromoLoading(false); }
  };

  const togglePromoActive = async (row: any, value: boolean) => {
    try {
      const resp = await fetch(`/api/admin/promo/codes/${row.id}`, { method: 'PUT', headers: buildAuthHeaders(), body: JSON.stringify({ is_active: value }) });
      if (!resp.ok) throw new Error();
      await loadPromo();
    } catch { message.error('Ошибка обновления промокода'); }
  };

  const deletePromo = async (row: any) => {
    try {
      const resp = await fetch(`/api/admin/promo/codes/${row.id}`, { method: 'DELETE', headers: buildAuthHeaders() });
      if (!resp.ok) throw new Error();
      await loadPromo();
    } catch { message.error('Ошибка удаления'); }
  };

  const loadRequests = async () => {
    try {
      setRequestsLoading(true);
      const resp = await fetch('/api/admin/registration/requests', { headers: buildAuthHeaders() });
      if (!resp.ok) throw new Error();
      const data = await resp.json();
      setRegRequests(Array.isArray(data.items) ? data.items : []);
    } catch { message.error('Ошибка загрузки заявок'); } finally { setRequestsLoading(false); }
  };

  const approveRequest = async (id: number) => {
    try {
      const resp = await fetch(`/api/admin/registration/requests/${id}/approve`, { method: 'POST', headers: buildAuthHeaders(), body: '{}' });
      if (!resp.ok) throw new Error();
      await loadRequests();
      message.success('Заявка подтверждена');
    } catch { message.error('Не удалось подтвердить'); }
  };

  const rejectRequest = async (id: number) => {
    try {
      const resp = await fetch(`/api/admin/registration/requests/${id}/reject`, { method: 'POST', headers: buildAuthHeaders(), body: '{}' });
      if (!resp.ok) throw new Error();
      await loadRequests();
    } catch { message.error('Не удалось отклонить'); }
  };

  const loadDocLinks = async () => {
    try {
      const resp = await fetch('/api/admin/settings?keys=registration.privacy_url,registration.security_url,registration.duty_admin_tg_id', { headers: buildAuthHeaders() });
      if (!resp.ok) throw new Error();
      const data = await resp.json();
      setDocPrivacyUrl(data.items?.['registration.privacy_url'] || '');
      setDocSecurityUrl(data.items?.['registration.security_url'] || '');
      setDutyAdminTgId(data.items?.['registration.duty_admin_tg_id'] || '');
    } catch { /* no-op */ }
  };

  const saveDocLink = async (key: 'registration.privacy_url' | 'registration.security_url', value: string) => {
    try {
      const resp = await fetch('/api/admin/settings', { method: 'POST', headers: buildAuthHeaders(), body: JSON.stringify({ key, value_text: value }) });
      if (!resp.ok) throw new Error();
      message.success('Ссылка сохранена');
    } catch { message.error('Ошибка сохранения ссылки'); }
  };

  const saveDutyAdmin = async () => {
    const value = dutyAdminTgId.trim();
    if (value && !/^\d+$/.test(value)) { message.warning('tg_id должен быть числом'); return; }
    try {
      const resp = await fetch('/api/admin/settings', { method: 'POST', headers: buildAuthHeaders(), body: JSON.stringify({ key: 'registration.duty_admin_tg_id', value_text: value }) });
      if (!resp.ok) throw new Error();
      message.success('Дежурный админ сохранён');
    } catch { message.error('Ошибка сохранения'); }
  };

  const runDevConnect = async () => {
    const owner = sessionStorage.getItem('tg_id') || getTelegramUser()?.id?.toString();
    if (!owner) { message.warning('Не найден tg_id пользователя'); return; }
    try {
      setDevConnectLoading(true);
      const resp = await fetch('/api/hyperloop/execute', {
        method: 'POST',
        headers: buildAuthHeaders(),
        body: JSON.stringify({ commands: `DEV.CONNECT owner="${owner}" branch="${devBranch}" session="${devSession}"` })
      });
      const data = await resp.json().catch(() => ({}));
      if (resp.ok && data && (data.ok === true || (Array.isArray(data.results) && data.results.every((x: any) => x?.ok)))) {
        message.success('DEV.CONNECT ok');
      } else {
        message.warning(`DEV.CONNECT: ${resp.status}`);
      }
      console.debug('DEV.CONNECT resp', data);
    } catch { message.error('Ошибка DEV.CONNECT'); } finally { setDevConnectLoading(false); }
  };

  const loadMyLocks = async () => {
    const owner = sessionStorage.getItem('tg_id') || getTelegramUser()?.id?.toString();
    try {
      setLocksLoading(true);
      const resp = await fetch('/api/hyperloop/execute', {
        method: 'POST',
        headers: buildAuthHeaders(),
        body: JSON.stringify({ commands: 'INSPECTOR.RUN key=plan.branch action=list' })
      });
      const data = await resp.json().catch(() => ({}));
      const items: Array<any> = [];
      const res = (Array.isArray(data?.results) ? data.results : []);
      const first = res[0] || {};
      const locks = first?.data?.locks || {};
      const branches = locks?.branches || {};
      Object.keys(branches).forEach((k) => {
        const v = branches[k];
        // Поддержка двух форматов: legacy {owner, session, ts} и новая {owners: { ownerId: {owner, session, ts} }}
        if (v && typeof v === 'object' && v.owners && typeof v.owners === 'object') {
          Object.keys(v.owners).forEach((ow) => {
            const om = v.owners[ow] || {};
            if (!owner || String(om?.owner) === String(owner)) {
              items.push({ key: k, owner: om?.owner, session: om?.session || '', ts: om?.ts || '' });
            }
          });
        } else {
          if (!owner || String(v?.owner) === String(owner)) {
            items.push({ key: k, owner: v?.owner, session: v?.session || '', ts: v?.ts || '' });
          }
        }
      });
      setMyBranches(items);
    } catch { /* no-op */ } finally { setLocksLoading(false); }
  };

  const buildHeaders = (): HeadersInit => ({ ...buildAuthHeaders() });

  const loadActivePersonality = async () => {
    try {
      setLoadingPersonality(true);
      const resp = await fetch('/api/admin/personality/active', { headers: buildHeaders() });
      const data = await resp.json();
      setActivePersonality(data);
    } catch {
      message.error('Не удалось загрузить активную личность');
    } finally {
      setLoadingPersonality(false);
    }
  };

  const reloadAll = async () => {
    try {
      setBatchLoading(true);
      await loadActivePersonality();
      await reloadPersonalityLists();
      await Promise.all([loadPromo(), loadRedemptions(), loadRequests(), loadDocLinks()]);
      message.success('Данные обновлены');
    } catch {
      message.error('Ошибка комплексного обновления');
    } finally {
      setBatchLoading(false);
    }
  };

  const definePersonality = async () => {
    try {
      const resp = await fetch('/api/admin/personality/define', {
        method: 'POST',
        headers: buildHeaders(),
        body: JSON.stringify({ version: defineVersion, sex: defineSex, anima_animus: defineAnima })
      });
      if (!resp.ok) throw new Error();
      const data = await resp.json();
      message.success(`Создана личность: ${data.id}`);
      setDefineModalOpen(false);
      await loadActivePersonality();
    } catch {
      message.error('Ошибка создания личности');
    }
  };

  const addNorm = async () => {
    const pid = activePersonality?.id;
    if (!pid) { message.warning('Нет активной личности'); return; }
    try {
      const resp = await fetch('/api/admin/personality/norm', {
        method: 'POST', headers: buildHeaders(),
        body: JSON.stringify({ personality_id: pid, key: normKey, title: normTitle, severity: normSeverity, scope: normScope, links: [] })
      });
      if (!resp.ok) throw new Error();
      message.success('Норма добавлена/обновлена');
    } catch { message.error('Ошибка добавления нормы'); }
  };

  const setTrait = async () => {
    const pid = activePersonality?.id;
    if (!pid) { message.warning('Нет активной личности'); return; }
    try {
      const resp = await fetch('/api/admin/personality/trait', {
        method: 'POST', headers: buildHeaders(),
        body: JSON.stringify({ personality_id: pid, key: traitKey, family: traitFamily, tendency: traitTendency, stability: traitStability, links: [] })
      });
      if (!resp.ok) throw new Error();
      message.success('Черта сохранена');
    } catch { message.error('Ошибка сохранения черты'); }
  };

  const setAttachment = async () => {
    const pid = activePersonality?.id;
    if (!pid) { message.warning('Нет активной личности'); return; }
    try {
      const resp = await fetch('/api/admin/personality/attachment', {
        method: 'POST', headers: buildHeaders(),
        body: JSON.stringify({ personality_id: pid, key: attachKey, baseline_weight: attachWeight, links: [] })
      });
      if (!resp.ok) throw new Error();
      message.success('Привязанность сохранена');
    } catch { message.error('Ошибка сохранения привязанности'); }
  };

  const setPolicy = async () => {
    const pid = activePersonality?.id;
    if (!pid) { message.warning('Нет активной личности'); return; }
    let parsed: any = null;
    try { parsed = JSON.parse(policyValue); } catch { message.warning('Value должен быть корректным JSON'); return; }
    try {
      const resp = await fetch('/api/admin/personality/policy', {
        method: 'POST', headers: buildHeaders(),
        body: JSON.stringify({ personality_id: pid, key: policyKey, value: parsed })
      });
      if (!resp.ok) throw new Error();
      message.success('Политика сохранена');
    } catch { message.error('Ошибка сохранения политики'); }
  };

  const activatePersonality = async () => {
    const pid = activePersonality?.id;
    if (!pid) { message.warning('Нет активной личности'); return; }
    if (!twoKeysReqId.trim()) { message.warning('Укажите request_id Two-Keys'); return; }
    try {
      const resp = await fetch('/api/admin/personality/activate', {
        method: 'POST', headers: buildHeaders(),
        body: JSON.stringify({ id: pid, two_keys: { request_id: twoKeysReqId.trim() } })
      });
      const data = await resp.json().catch(() => ({}));
      if (!resp.ok || data?.ok !== true) throw new Error();
      message.success('Личность активирована');
      await loadActivePersonality();
    } catch { message.error('Ошибка активации (Two-Keys)'); }
  };

  // === Two-Keys UI actions ===
  const createTwoKeysRequest = async () => {
    const body: any = { operation: tkOperation, scope: tkScope, reason: tkReason };
    if (typeof tkTtl === 'number' && tkTtl > 0) body.ttl_minutes = tkTtl;
    try {
      const resp = await fetch('/api/admin/two-keys/requests', {
        method: 'POST',
        headers: buildHeaders(),
        body: JSON.stringify(body)
      });
      const data = await resp.json().catch(() => ({} as any));
      if (!resp.ok) throw new Error(String(data?.error || resp.status));
      const rid = String(data?.id || data?.request_id || data?.rid || '').trim();
      if (rid) {
        setTwoKeysReqId(rid);
        message.success(`Создана Two-Keys заявка: ${rid}`);
      } else {
        message.success('Two-Keys заявка создана');
      }
    } catch (e: any) {
      const msg = String(e?.message || 'Ошибка создания Two-Keys заявки');
      message.error(msg);
    }
  };

  const approveTwoKeysRequest = async () => {
    const rid = twoKeysReqId.trim();
    if (!rid) { message.warning('Укажите request_id'); return; }
    try {
      const resp = await fetch('/api/admin/two-keys/approve', {
        method: 'POST',
        headers: buildHeaders(),
        body: JSON.stringify({ request_id: rid })
      });
      const data = await resp.json().catch(() => ({} as any));
      if (!resp.ok) {
        if (resp.status === 403) { message.error('403: нет аппрува/прав для подтверждения'); return; }
        throw new Error(String(data?.error || resp.status));
      }
      message.success('Two-Keys заявка подтверждена');
    } catch (e: any) {
      const msg = String(e?.message || 'Ошибка подтверждения Two-Keys');
      message.error(msg);
    }
  };

  useEffect(() => { void loadPromo(); void loadRedemptions(); void loadRequests(); void loadDocLinks(); void loadActivePersonality(); }, []);

  return (
    <div style={{ padding: 16 }}>
      <Typography.Title level={3} style={{ marginBottom: 16 }}>Панель Администратора</Typography.Title>

      <Space direction="vertical" style={{ width: '100%' }} size="large">
        <Card title="Ссылки документов">
          <Space direction="vertical" style={{ width: '100%' }}>
            <Input placeholder="Ссылка на политику персональных данных" value={docPrivacyUrl} onChange={(e) => setDocPrivacyUrl(e.target.value)} />
            <Space>
              <Button onClick={() => saveDocLink('registration.privacy_url', docPrivacyUrl)} type="primary">Сохранить</Button>
              <Button onClick={loadDocLinks}>Обновить</Button>
            </Space>
            <Input placeholder="Ссылка на политику безопасности" value={docSecurityUrl} onChange={(e) => setDocSecurityUrl(e.target.value)} />
            <Space>
              <Button onClick={() => saveDocLink('registration.security_url', docSecurityUrl)} type="primary">Сохранить</Button>
              <Button onClick={loadDocLinks}>Обновить</Button>
            </Space>
            <Input placeholder="tg_id дежурного администратора" value={dutyAdminTgId} onChange={(e) => setDutyAdminTgId(e.target.value)} />
            <Space>
              <Button onClick={saveDutyAdmin} type="primary">Сохранить дежурного</Button>
              <Button onClick={loadDocLinks}>Обновить</Button>
            </Space>
          </Space>
        </Card>

        <Card title="Быстрые действия DEV">
          <Space>
            <Input placeholder="Ветка (branch)" value={devBranch} onChange={(e) => setDevBranch(e.target.value)} style={{ width: 240 }} />
            <Input placeholder="Сессия (session)" value={devSession} onChange={(e) => setDevSession(e.target.value)} style={{ width: 180 }} />
            <Button type="primary" onClick={runDevConnect} loading={devConnectLoading}>DEV.CONNECT</Button>
          </Space>
        </Card>

        <Card title="Активные ветки (мои)">
          <Space direction="vertical" style={{ width: '100%' }}>
            <Space>
              <Button onClick={loadMyLocks} loading={locksLoading}>Обновить</Button>
            </Space>
            <Table
              rowKey={(r) => r.key}
              columns={[
                { title: 'Ветка', dataIndex: 'key' },
                { title: 'Владелец (tg_id)', dataIndex: 'owner', width: 160 },
                { title: 'Сессия', dataIndex: 'session', width: 160 },
                { title: 'TS', dataIndex: 'ts', width: 220 },
              ] as any}
              dataSource={myBranches}
              pagination={false}
              size="small"
              scroll={{ x: true }}
            />
          </Space>
        </Card>

        <Card title="Two-Keys (заявка / аппрув)">
          <Space direction="vertical" style={{ width: '100%' }} size="middle">
            <Space wrap>
              <Input placeholder="operation" value={tkOperation} onChange={(e) => setTkOperation(e.target.value)} style={{ width: 260 }} />
              <Input placeholder="scope" value={tkScope} onChange={(e) => setTkScope(e.target.value)} style={{ width: 180 }} />
              <Input placeholder="reason" value={tkReason} onChange={(e) => setTkReason(e.target.value)} style={{ width: 320 }} />
              <InputNumber placeholder="ttl_minutes" value={tkTtl} onChange={(v) => setTkTtl(typeof v === 'number' ? v : undefined)} min={1} max={24*60} />
              <Button type="primary" onClick={createTwoKeysRequest}>Создать заявку</Button>
            </Space>
            <Space>
              <Input placeholder="two_keys.request_id" value={twoKeysReqId} onChange={(e) => setTwoKeysReqId(e.target.value)} style={{ width: 360 }} />
              <Button onClick={approveTwoKeysRequest}>Подтвердить (APPROVE)</Button>
            </Space>
          </Space>
        </Card>

        <Card title="Промокоды" loading={promoLoading}>
          <Space direction="vertical" style={{ width: '100%' }} size="middle">
            <Space>
              <Input placeholder="Код" value={newPromoCode} onChange={(e) => setNewPromoCode(e.target.value)} />
              <Input placeholder="Роль (basic/premium/vip)" value={newPromoRole} onChange={(e) => setNewPromoRole(e.target.value)} />
              <InputNumber placeholder="Лимит" value={newPromoLimit} onChange={setNewPromoLimit} min={1} />
              <Button type="primary" onClick={createPromo}>Создать</Button>
              <Button onClick={loadPromo}>Обновить</Button>
            </Space>
            <Table
              rowKey={(r) => r.id}
              columns={[
                { title: 'Код', dataIndex: 'code' },
                { title: 'Роль', dataIndex: 'role_name', width: 140 },
                { title: 'Лимит', dataIndex: 'total_limit', width: 100 },
                { title: 'Активировано', dataIndex: 'redeemed_count', width: 130 },
                { title: 'Активен', key: 'is_active', width: 120, render: (_: any, r: any) => (<Checkbox checked={r.is_active} onChange={(e) => togglePromoActive(r, e.target.checked)} />) },
                { title: 'Действия', key: 'actions', width: 140, render: (_: any, r: any) => (<Button danger size="small" onClick={() => deletePromo(r)}>Удалить</Button>) },
              ] as any}
              dataSource={promoCodes}
              pagination={{ pageSize: 10 }}
              size="small"
              scroll={{ x: true }}
            />
          </Space>
        </Card>

        <Card title="Активации промокодов">
          <Table
            rowKey={(r) => r.id}
            columns={[
              { title: 'ID', dataIndex: 'id', width: 80 },
              { title: 'Код', dataIndex: 'promo_code', width: 160 },
              { title: 'Пользователь', key: 'user', render: (_: any, r: any) => `${r.user_id} / tg=${r.tg_id}` },
              { title: 'Когда', dataIndex: 'redeemed_at', width: 200 },
              { title: 'Заметка', dataIndex: 'note' },
            ] as any}
            dataSource={redemptions}
            pagination={{ pageSize: 10 }}
            size="small"
            scroll={{ x: true }}
          />
        </Card>

        <Card title="Заявки на регистрацию" loading={requestsLoading}>
          <Table
            rowKey={(r) => r.id}
            columns={[
              { title: 'ID', dataIndex: 'id', width: 80 },
              { title: 'Статус', dataIndex: 'status', width: 120 },
              { title: 'Пользователь', key: 'user', render: (_: any, r: any) => `${r.user?.id} / tg=${r.user?.tg_id}` },
              { title: 'Имя', key: 'fn', render: (_: any, r: any) => `${r.user?.first_name || ''} ${r.user?.last_name || ''}` },
              { title: 'Желаемая роль', dataIndex: 'desired_role', width: 140 },
              { title: 'План', dataIndex: 'desired_plan', width: 120 },
              { title: 'Комментарий', dataIndex: 'comment' },
              { title: 'Действия', key: 'actions', width: 220, render: (_: any, r: any) => (
                <Space>
                  <Button type="primary" size="small" onClick={() => approveRequest(r.id)} disabled={r.status !== 'pending'}>Подтвердить</Button>
                  <Button danger size="small" onClick={() => rejectRequest(r.id)} disabled={r.status !== 'pending'}>Отклонить</Button>
                </Space>
              ) },
            ] as any}
            dataSource={regRequests}
            pagination={{ pageSize: 10 }}
            size="small"
            scroll={{ x: true }}
          />
        </Card>

        <HyperloopDSLValidator title="Hyperloop DSL — валидатор/нормализация (общий)" />

        {/* P51 Personality Admin */}
        <Card title="Личность Соул (P51)" loading={loadingPersonality || listsLoading}>
          <Space direction="vertical" style={{ width: '100%' }} size="middle">
            <Space>
              <Button onClick={loadActivePersonality}>Обновить</Button>
              <Button onClick={reloadAll} loading={batchLoading} type="default">Обновить всё</Button>
              <Button type="primary" onClick={() => setDefineModalOpen(true)}>Создать личность</Button>
            </Space>
            <div style={{ padding: '8px 0' }}>
              <Typography.Text>Активная личность:</Typography.Text>
              <div>
                {activePersonality?.id ? (
                  <div>
                    <div>ID: <code>{activePersonality.id}</code></div>
                    <div>Версия: {activePersonality.version}</div>
                    <div>Пол: {activePersonality.sex}</div>
                    <div>Статус: {activePersonality.is_active ? 'активна' : 'не активна'}</div>
                    <div>Обновлена: {String(activePersonality.updated_at || '')}</div>
                  </div>
                ) : (
                  <Typography.Text type="secondary">Нет активной личности</Typography.Text>
                )}
              </div>
              <Space style={{ marginTop: 8 }}>
                <Button onClick={reloadPersonalityLists} loading={listsLoading}>Загрузить списки/связи</Button>
              </Space>
            </div>

            <Card size="small" title="Нормы">
              <Space>
                <Input placeholder="key" value={normKey} onChange={(e) => setNormKey(e.target.value)} style={{ width: 160 }} />
                <Input placeholder="title" value={normTitle} onChange={(e) => setNormTitle(e.target.value)} style={{ width: 200 }} />
                <Input placeholder="scope (duty/honesty/...)" value={normScope} onChange={(e) => setNormScope(e.target.value)} style={{ width: 200 }} />
                <InputNumber placeholder="severity" value={normSeverity} onChange={(v) => setNormSeverity(Number(v || 0))} min={0} max={1} step={0.05} />
                <Button type="primary" onClick={addNorm}>Сохранить норму</Button>
              </Space>
            </Card>
            <Table
              rowKey={(r) => r.id}
              columns={[{ title: 'key', dataIndex: 'key' }, { title: 'title', dataIndex: 'title' }, { title: 'severity', dataIndex: 'severity' }, { title: 'scope', dataIndex: 'scope' }] as any}
              dataSource={norms}
              size="small"
              pagination={{ pageSize: 5 }}
            />

            <Card size="small" title="Черты">
              <Space>
                <Input placeholder="key" value={traitKey} onChange={(e) => setTraitKey(e.target.value)} style={{ width: 200 }} />
                <Input placeholder="family (OCEAN/Jung/...)" value={traitFamily} onChange={(e) => setTraitFamily(e.target.value)} style={{ width: 220 }} />
                <InputNumber placeholder="tendency" value={traitTendency} onChange={(v) => setTraitTendency(Number(v || 0))} min={-1} max={1} step={0.05} />
                <InputNumber placeholder="stability" value={traitStability} onChange={(v) => setTraitStability(Number(v || 0))} min={0} max={1} step={0.05} />
                <Button type="primary" onClick={setTrait}>Сохранить черту</Button>
              </Space>
            </Card>
            <Table
              rowKey={(r) => r.id}
              columns={[{ title: 'key', dataIndex: 'key' }, { title: 'family', dataIndex: 'family' }, { title: 'tendency', dataIndex: 'tendency' }, { title: 'stability', dataIndex: 'stability' }] as any}
              dataSource={traits}
              size="small"
              pagination={{ pageSize: 5 }}
            />

            <Card size="small" title="Привязанности">
              <Space>
                <Input placeholder="key" value={attachKey} onChange={(e) => setAttachKey(e.target.value)} style={{ width: 200 }} />
                <InputNumber placeholder="baseline_weight" value={attachWeight} onChange={(v) => setAttachWeight(Number(v || 0))} min={0} max={1} step={0.05} />
                <Button type="primary" onClick={setAttachment}>Сохранить привязанность</Button>
              </Space>
            </Card>
            <Table
              rowKey={(r) => r.id}
              columns={[{ title: 'key', dataIndex: 'key' }, { title: 'baseline_weight', dataIndex: 'baseline_weight' } , { title: 'growth_policy', dataIndex: 'growth_policy' }] as any}
              dataSource={attachments}
              size="small"
              pagination={{ pageSize: 5 }}
            />

            <Card size="small" title="Политики">
              <Space direction="vertical" style={{ width: '100%' }}>
                <Space>
                  <Select style={{ width: 280 }} value={policyKey} onChange={(v) => setPolicyKey(v)}
                    options={[
                      { value: 'processor.multipliers', label: 'processor.multipliers' },
                      { value: 'search.bias', label: 'search.bias' },
                      { value: 'router.hints', label: 'router.hints' },
                      { value: 'sleep.profile', label: 'sleep.profile' },
                    ]}
                  />
                  <Button type="primary" onClick={setPolicy}>Сохранить политику</Button>
                </Space>
                <Input.TextArea rows={6} value={policyValue} onChange={(e) => setPolicyValue(e.target.value)} placeholder="JSON value" />
              </Space>
            </Card>
            <Table
              rowKey={(r) => r.key}
              columns={[{ title: 'key', dataIndex: 'key' }, { title: 'value', dataIndex: 'value' }] as any}
              dataSource={policies}
              size="small"
              pagination={{ pageSize: 5 }}
            />

            <Card size="small" title="Активация (Two-Keys)">
              <Space>
                <Input placeholder="two_keys.request_id" value={twoKeysReqId} onChange={(e) => setTwoKeysReqId(e.target.value)} style={{ width: 360 }} />
                <Button type="primary" onClick={activatePersonality}>Активировать</Button>
              </Space>
            </Card>

            <Card size="small" title="Связи (матрица)">
              <Table
                rowKey={(r) => `${r.element_kind}:${r.element_id}:${r.core_quant_id}`}
                columns={[
                  { title: 'element_kind', dataIndex: 'element_kind' },
                  { title: 'element_id', dataIndex: 'element_id' },
                  { title: 'core_quant_id', dataIndex: 'core_quant_id' },
                  { title: 'relation_weight', dataIndex: 'relation_weight' },
                ] as any}
                dataSource={links}
                size="small"
                pagination={{ pageSize: 10 }}
              />
            </Card>
          </Space>
        </Card>
      </Space>

      <Modal open={defineModalOpen} onCancel={() => setDefineModalOpen(false)} onOk={definePersonality} title="Создать личность">
        <Space direction="vertical" style={{ width: '100%' }}>
          <Space>
            <Typography.Text>Пол:</Typography.Text>
            <Select value={defineSex} onChange={(v) => setDefineSex(v)} options={[{ value: 'male', label: 'male' }, { value: 'female', label: 'female' }]} style={{ width: 180 }} />
          </Space>
          <Space>
            <Typography.Text>Версия:</Typography.Text>
            <Input value={defineVersion} onChange={(e) => setDefineVersion(e.target.value)} style={{ width: 220 }} />
          </Space>
          <Space>
            <Typography.Text>anima/animus:</Typography.Text>
            <InputNumber value={defineAnima} onChange={(v) => setDefineAnima(Number(v || 0))} min={0} max={1} step={0.05} />
          </Space>
        </Space>
      </Modal>
    </div>
  );
};

export default AdminPanel;



